6: /* ------------------------------------------------------------------ *
7:  *  SUBLEVEL 02 — a real facility: wide halls, enclosed rooms with
8:  *  doorways and headers, furniture, signage and a creature.
9:  * ------------------------------------------------------------------ */
10: export function buildFacility(scene, { onEvidence, onCaught }) {
11:   const group = new THREE.Group();
12:   group.name = 'Sublevel laboratory';
13:   group.visible = false;
14:   scene.add(group);
15: 
16:   const F = { minX: -30, maxX: 30, minZ: -40, maxZ: 14, h: 4.4 };
17:   const wallMat = mat('facility wall', 0x7a8177, 0.96);
18:   const darkWall = mat('facility wall dark', 0x596157, 0.95);
19:   const concrete = mat('facility concrete', 0x84877a, 0.97);
20:   const metal = mat('facility steel', 0x3d4540, 0.5, { metalness: 0.4 });
21:   const floorMat = mat('lab floor', 0x59615a, 0.95);
22:   const ceilingMat = mat('lab ceiling', 0x525a4f, 0.96);
23: 
24:   const lights = [];
25:   const flickerLights = [];
26:   group.add(new THREE.AmbientLight(0x85937f, 1.35));
27: 
28:   /* ---------------- structural helpers ---------------- */
29:   function wall(x1, z1, x2, z2, opts = {}) {
30:     const h = opts.h ?? F.h, th = opts.th ?? 0.3, m = opts.m ?? wallMat;
31:     const alongX = Math.abs(z2 - z1) < 0.001;
32:     const a = alongX ? Math.min(x1, x2) : Math.min(z1, z2);
33:     const b = alongX ? Math.max(x1, x2) : Math.max(z1, z2);
34:     const doors = (opts.doors || []).slice().sort((p, q) => p.at - q.at);
35:     const segment = (s, e) => {
36:       const len = e - s;
37:       if (len <= 0.03) return;
38:       if (alongX) {
39:         box(group, 'facility wall', (s + e) / 2, h / 2, z1, len, h, th, m);
40:         addSolid('lab', (s + e) / 2, z1, len / 2, th / 2);
41:       } else {
42:         box(group, 'facility wall', x1, h / 2, (s + e) / 2, th, h, len, m);
43:         addSolid('lab', x1, (s + e) / 2, th / 2, len / 2);
44:       }
45:     };
46:     const header = (s, e, dh) => {
47:       if (dh >= h - 0.05) return;
48:       if (alongX) box(group, 'door header', (s + e) / 2, (dh + h) / 2, z1, e - s, h - dh, th, m);
49:       else box(group, 'door header', x1, (dh + h) / 2, (s + e) / 2, th, h - dh, e - s, m);
50:     };
51:     let cursor = a;
52:     for (const d of doors) {
53:       const ds = d.at - d.w / 2, de = d.at + d.w / 2, dh = d.h ?? 2.65;
54:       segment(cursor, ds);
55:       header(ds, de, dh);
56: 
57:       // metal door frame
58:       if (alongX) {
59:         box(group, 'door jamb', ds, dh / 2, z1, 0.09, dh, th + 0.08, metal);
60:         box(group, 'door jamb', de, dh / 2, z1, 0.09, dh, th + 0.08, metal);
61:         box(group, 'door lintel', (ds + de) / 2, dh + 0.045, z1, de - ds + 0.18, 0.09, th + 0.08, metal);
62:         box(group, 'threshold', (ds + de) / 2, 0.012, z1, de - ds, 0.024, th + 0.08,
63:           mat('threshold', 0x2a2e2a, 0.95), { cast: false });
64:       } else {
65:         box(group, 'door jamb', x1, dh / 2, ds, th + 0.08, dh, 0.09, metal);
66:         box(group, 'door jamb', x1, dh / 2, de, th + 0.08, dh, 0.09, metal);
67:         box(group, 'door lintel', x1, dh + 0.045, (ds + de) / 2, th + 0.08, 0.09, de - ds + 0.18, metal);
68:         box(group, 'threshold', x1, 0.012, (ds + de) / 2, th + 0.08, 0.024, de - ds,
69:           mat('threshold', 0x2a2e2a, 0.95), { cast: false });
70:       }
71: 
72:       if (d.glass) {
73:         const paneMat = mat('observation glass', 0x9ab9a7, 0.1,
74:           { transparent: true, opacity: 0.17, metalness: 0.35, side: THREE.DoubleSide });
75:         const pane = new THREE.Mesh(new THREE.PlaneGeometry(de - ds - 0.12, dh - 0.12), paneMat);
76:         if (alongX) { pane.position.set((ds + de) / 2, dh / 2 + 0.02, z1 + 0.02); }
77:         else { pane.position.set(x1 + 0.02, dh / 2 + 0.02, (ds + de) / 2); pane.rotation.y = Math.PI / 2; }
78:         group.add(pane);
79:         if (alongX) addSolid('lab', (ds + de) / 2, z1, (de - ds) / 2, th / 2 + 0.05);
80:         else addSolid('lab', x1, (ds + de) / 2, th / 2 + 0.05, (de - ds) / 2);
81:       } else if (d.panel !== false) {
82:         const pw = Math.min(0.85, d.w * 0.38);
83:         const doorMat = mat('sliding door', 0x3e4540, 0.62, { metalness: 0.25 });
84:         if (alongX) {
85:           box(group, 'sliding door', ds + pw / 2 + 0.03, 1.29, z1, pw, 2.58, 0.07, doorMat);
86:         } else {
87:           box(group, 'sliding door', x1, 1.29, ds + pw / 2 + 0.03, 0.07, 2.58, pw, doorMat);
88:         }
89:       }
90:       cursor = de;
91:     }
92:     segment(cursor, b);
93:   }
