95:   function floorPatch(name, x1, z1, x2, z2, color, rough = 0.95) {
96:     const lifted = new THREE.Color(color).multiplyScalar(1.38).getHex();
97:     box(group, name, (x1 + x2) / 2, 0.012, (z1 + z2) / 2, x2 - x1, 0.024, z2 - z1,
98:       mat(name, lifted, rough), { cast: false });
99:   }
100: 
101:   function ceilingLight(x, z, color, intensity, flicker = false, dist = 12) {
102:     box(group, 'light housing', x, 4.36, z, 2.1, 0.1, 0.6, mat('light housing', 0x333a35, 0.7));
103:     const tube = box(group, 'light tube', x, 4.3, z, 1.85, 0.045, 0.3,
104:       mat('tube' + color + intensity, color, 0.3, { emissive: color, emissiveIntensity: 1.5 }), { cast: false });
105:     const l = new THREE.PointLight(color, intensity * 2.2, dist, 2);
106:     l.position.set(x, 4.02, z);
107:     group.add(l);
108:     lights.push(l);
109:     const entry = { l, tube, flicker, base: intensity * 2.2, seed: Math.random() * 10 };
110:     if (flicker) flickerLights.push(entry);
111:     return entry;
112:   }
113: 
114:   function pipeRun(x, z, len, axis, y, r = 0.09, color = 0x38413b, name = 'pipe') {
115:     const m = cylinder(group, name, x, y, z, r, r, len, mat(name + color, color, 0.5, { metalness: 0.5 }), 8);
116:     if (axis === 'z') m.rotation.x = Math.PI / 2; else m.rotation.z = Math.PI / 2;
117:     return m;
118:   }
119: 
120:   function bloodStain(x, z, sx = 1, sz = 1, ry = 0) {
121:     const m = box(group, 'blood stain', x, 0.026, z, sx, 0.012, sz,
122:       mat('blood stain', 0x3a1c18, 0.95), { cast: false });
123:     m.rotation.y = ry;
124:     return m;
125:   }
126: 
127:   /* ---------------- shell ---------------- */
128:   box(group, 'sublevel floor', 0, -0.15, -13, 60, 0.3, 54, floorMat);
129:   box(group, 'sublevel ceiling', 0, 4.55, -13, 60, 0.3, 54, ceilingMat);
130: 
131:   wall(-30, 14, 30, 14, { m: concrete, doors: [{ at: 0, w: 3.6, h: 3.15 }] });
132:   wall(-30, -40, 30, -40, { m: darkWall });
133:   wall(-30, -40, -30, 14, { m: concrete });
134:   wall(30, -40, 30, 14, { m: concrete });
135: 
136:   // north row, N corridor, mid blocks, S corridor, deep rooms
137:   wall(-30, 10.5, 30, 10.5, { doors: [{ at: -23, w: 2.4 }, { at: -11, w: 2.4 }, { at: 0, w: 3.4, h: 3.0 }, { at: 11, w: 2.4 }, { at: 23, w: 2.4 }] });
138:   wall(-17, 10.5, -17, 14, {});
139:   wall(17, 10.5, 17, 14, {});
140:   wall(-4, 10.5, -4, 14, {});
141:   wall(4, 10.5, 4, 14, {});
142: 
143:   wall(-30, 5, 30, 5, { doors: [{ at: -23, w: 2.4 }, { at: -10.5, w: 2.4 }, { at: 0, w: 7.4, h: 3.5 }, { at: 10.5, w: 2.4 }, { at: 23, w: 2.4 }] });
144:   wall(-17, -12, -17, 5, { doors: [{ at: -3.5, w: 2.4 }] });
145:   wall(17, -12, 17, 5, { doors: [{ at: -3.5, w: 2.6, glass: true }] });
146: 
147:   wall(-30, -12, 30, -12, { doors: [{ at: -23, w: 2.4 }, { at: -10.5, w: 2.4 }, { at: 0, w: 7.4, h: 3.5 }, { at: 10.5, w: 2.4 }, { at: 23, w: 2.4 }] });
148:   wall(-4, -34, -4, 5, { doors: [{ at: -28, w: 2.4 }, { at: -14.5, w: 5.2, h: 3.5 }, { at: -2, w: 2.4 }] });
149:   wall(4, -34, 4, 5, { doors: [{ at: -28, w: 2.4 }, { at: -14.5, w: 5.2, h: 3.5 }, { at: -2, w: 2.4 }] });
150: 
151:   wall(-30, -17, 30, -17, { doors: [{ at: -23, w: 2.4 }, { at: -10.5, w: 2.4 }, { at: 0, w: 7.4, h: 3.5 }, { at: 10.5, w: 2.4 }, { at: 23, w: 2.4 }] });
152:   wall(-17, -34, -17, -17, { doors: [{ at: -25.5, w: 2.4 }] });
153:   wall(17, -34, 17, -17, { doors: [{ at: -25.5, w: 2.4 }] });
154:   wall(-30, -34, 30, -34, { m: darkWall, doors: [{ at: 0, w: 6, h: 3.6 }] });
155:   wall(-12, -40, -12, -34, { m: darkWall });
156:   wall(12, -40, 12, -34, { m: darkWall });
