158:   /* ---------------- floors ---------------- */
159:   floorPatch('vestibule floor', -4, 10.5, 4, 14, 0x484b42);
160:   floorPatch('admin floor', -30, 10.5, -4, 14, 0x4a4439, 0.98);
161:   floorPatch('security floor', 4, 10.5, 30, 14, 0x41463d);
162:   floorPatch('north hall floor', -30, 5, 30, 10.5, 0x3f4540);
163:   floorPatch('west mid floor', -30, -12, -4, 5, 0x434e46);
