171:   // tile seams + drains
172:   for (let z = -33; z < 13; z += 2) box(group, 'floor seam', 0, 0.026, z, 7.5, 0.012, 0.045, mat('floor seam', 0x2c312c, 0.95), { cast: false });
173:   for (let x = -28; x < 29; x += 2) box(group, 'hall seam', x, 0.026, 7.75, 0.045, 0.012, 5.3, mat('hall seam', 0x2c312c, 0.95), { cast: false });
174:   for (const [x, z] of [[0, 1], [0, -8], [0, -23], [-9, 7.7], [9, 7.7], [0, -14.5]]) {
175:     box(group, 'floor drain', x, 0.03, z, 0.55, 0.02, 0.55, mat('drain grate', 0x232824, 0.6, { metalness: 0.5 }), { cast: false });
176:     for (let i = 0; i < 4; i++) box(group, 'drain slot', x - 0.2 + i * 0.13, 0.042, z, 0.05, 0.01, 0.45, mat('drain slot', 0x101310, 0.8), { cast: false });
177:   }
178: 
179:   /* ---------------- ceiling lights ---------------- */
180:   ceilingLight(0, 12.3, 0xffc789, 15, false, 10);
181:   ceilingLight(-20, 7.7, 0xbfd4c2, 11, false, 12);
182:   ceilingLight(-7, 7.7, 0xbfd4c2, 11, false, 12);
183:   ceilingLight(7, 7.7, 0xbfd4c2, 11, true, 12);
184:   ceilingLight(20, 7.7, 0xbfd4c2, 11, false, 12);
185:   ceilingLight(0, 1.5, 0xc3d6c6, 12, false, 12);
186:   ceilingLight(0, -9, 0xc3d6c6, 12, true, 12);
187:   ceilingLight(0, -20, 0xc3d6c6, 12, false, 12);
188:   ceilingLight(0, -30, 0xff6a45, 13, true, 12);
189:   ceilingLight(-20, -14.5, 0xbfd4c2, 10, false, 12);
190:   ceilingLight(8, -14.5, 0xbfd4c2, 10, true, 12);
191:   ceilingLight(20, -14.5, 0xbfd4c2, 10, false, 12);
