201:   ceilingLight(-23.5, -25.5, 0xffb16b, 9, true, 11);
202:   ceilingLight(-10.5, -25.5, 0xff7a52, 12, false, 11);
203:   ceilingLight(10.5, -25.5, 0xd8e3d5, 16, false, 12);
204:   ceilingLight(23.5, -25.5, 0xff904d, 13, true, 12);
205:   const chamberLamp = ceilingLight(0, -36.4, 0xff4f35, 18, false, 13);
