207:   // dead fixtures keep the halls visually continuous
208:   for (const [x, z] of [[-13.5, 7.7], [13.5, 7.7], [0, -4], [0, -25], [-13.5, -14.5], [13.5, -14.5]]) {
209:     box(group, 'dead light housing', x, 4.36, z, 2.1, 0.1, 0.6, mat('light housing', 0x333a35, 0.7));
210:     box(group, 'dead tube', x, 4.3, z, 1.85, 0.045, 0.3, mat('dead tube', 0x5b655c, 0.7, { emissive: 0x1c241e, emissiveIntensity: 0.3 }), { cast: false });
211:   }
