213:   /* ---------------- pipes / ceiling detail ---------------- */
214:   pipeRun(-2.7, -13, 52, 'z', 4.18, 0.1, 0x3a423c);
215:   pipeRun(-2.7, -13, 52, 'z', 4.02, 0.055, 0x4c554d);
