231:   P.addSign(group, 'MORGUE', '', -10.5, 3.15, -12.17, Math.PI);
232:   P.addSign(group, 'RESEARCH', '', 10.5, 3.15, -12.17, Math.PI);
233:   P.addSign(group, 'OBSERVATION', '', 23, 3.15, -12.17, Math.PI);
234:   P.addSign(group, 'STORAGE', 'SUPPLIES', -23, 3.15, -16.83, 0);
235:   P.addSign(group, 'GENERATOR', 'POWER', -10.5, 3.15, -16.83, 0);
236:   P.addSign(group, 'THEATRE', 'SURGERY', 10.5, 3.15, -16.83, 0);
