298:   P.officeDesk(group, -19.6, 13.05, 0, { w: 1.8, d: 0.9, monitors: 0 });
299:   P.officeChair(group, -19.6, 12.2, Math.PI);
300:   P.cabinet(group, -29.4, 12.3, 1.6, 0.55, 1.9, Math.PI / 2);
