325: /* ------------------------------ movement ---------------------------- */
326: function collides(x, z) {
327:   const radius = 0.3;
328:   if (activeArea === 'lab') {
329:     const F = facility.F;
330:     if (x < F.minX + radius || x > F.maxX - radius || z < F.minZ + radius || z > F.maxZ - radius) return true;
331:     return blocked('lab', x, z, radius);
332:   }
333:   if (activeArea === 'room') {
334:     if (x < -5.55 || x > 5.48 || z < -5.5 || z > 5.5) return true;
335:     if (Math.abs(x + 1.6) < 1.9 && z > 0.78 && z < 2.1) return true;
336:     if (Math.abs(x + 1.4) < 1.2 && z > 2.42 && z < 3.72) return true;
337:     if (x > 2.25 && x < 5.1 && z > 1.75 && z < 4.5) return true;
338:   }
339:   if (activeArea === 'lot') {
340:     if (x < -23 || x > 23 || z < -24.0 || z > 16.5) return true;
341:     if (Math.abs(x) < 1.35 && z > 6.05 && z < 10.95) return true;
342:   }
343:   return false;
344: }
