346: function move(dt) {
347:   let forward = (keys.has('w') || keys.has('arrowup') ? 1 : 0) - (keys.has('s') || keys.has('arrowdown') ? 1 : 0);
348:   let side = (keys.has('d') || keys.has('arrowright') ? 1 : 0) - (keys.has('a') || keys.has('arrowleft') ? 1 : 0);
349:   if (!forward && !side) return;
350:   const length = Math.hypot(forward, side); forward /= length; side /= length;
351:   const speed = (keys.has('shift') ? 5.2 : 3.0) * dt;
352:   const dx = (-Math.sin(yaw) * forward + Math.cos(yaw) * side) * speed;
353:   const dz = (-Math.cos(yaw) * forward - Math.sin(yaw) * side) * speed;
354:   if (!collides(player.position.x + dx, player.position.z)) player.position.x += dx;
355:   if (!collides(player.position.x, player.position.z + dz)) player.position.z += dz;
356: }
