358: /* ------------------------------ game loop --------------------------- */
359: function update(dt) {
360:   elapsed += dt;
361:   move(dt);
362:   camera.rotation.set(pitch, yaw, 0, 'YXZ');
363: 
364:   if (activeArea === 'lab') {
365:     if (player.position.z > 13.25) {
366:       if (evidence >= 5) {
367:         changeArea('lot');
368:         player.position.set(-10, 0, -21.3); yaw = Math.PI;
369:         setObjective('Get to the car', 'You have all five recordings. Leave before it follows.');
370:         toast('BACK OUTSIDE · GET TO THE CAR');
371:       } else {
372:         player.position.z = 13.25;
373:       }
374:     }
375:     facility.update(dt, player.position, elapsed, !ui.note.classList.contains('hidden'));
376:   }
377: 
378:   for (const area of [lot]) {
379:     for (const l of area.userData.lamps || []) {
380:       if (Math.random() < dt * (l.userData.flicker ? 2.4 : 0.3)) l.intensity *= 0.14;
381:       else l.intensity = Math.min(l.userData.flicker ? 10 : 8, l.intensity + dt * 10);
382:     }
383:   }
384: 
385:   if (activeArea === 'lot' && doorOpened && player.position.z < -24.0) player.position.z = -24.0;
386:   if (toastTimer > 0) { toastTimer -= dt; if (toastTimer <= 0) ui.toast.classList.remove('show'); }
387:   const seconds = Math.floor(elapsed), clockEl = $('#clock');
388:   if (clockEl) clockEl.textContent = `02:${String(13 + Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`;
389:   updatePrompt();
390: }
